mapper.select:
select t.heartbeat_time,t.heartbeat_time heartbeatTime,t.machine_id,t.machine_id
machineId,t.machine_code,t.machine_code machineCode,t.location_name,t.location_name
locationName,t.factory_id,t.factory_id factoryId,t.status_cd,t.status_cd
statusCd,t.state,t.community_id,t.community_id communityId,t.machine_name,t.machine_name machineName,
lmf.factory_name factoryName, td.name stateName
from lamp_machine t
left join lamp_machine_factory lmf on t.factory_id = lmf.factory_id and lmf.status_cd = '0'
left join t_dict td on t.state = td.status_cd and td.table_name = 'lamp_machine' and td.table_columns = 'state'
where 1 =1

    and t.heartbeat_time= #{heartbeatTime}


    and t.machine_id= #{machineId}


    and t.machine_code like concat('%', #{machineCode}, '%')


    and t.location_name like concat('%', #{locationName}, '%')


    and t.factory_id= #{factoryId}


    and t.status_cd= #{statusCd}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.machine_name like concat('%', #{machineName}, '%')

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update lamp_machine t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.heartbeat_time= #{heartbeatTime}


    , t.machine_code= #{machineCode}


    , t.location_name= #{locationName}


    , t.factory_id= #{factoryId}


    , t.state= #{state}


    , t.community_id= #{communityId}


    , t.machine_name= #{machineName}

where 1=1

    and t.machine_id= #{machineId}

mapper.select:
select count(1) count
from lamp_machine t
where 1 =1

    and DATE_ADD(t.heartbeat_time, INTERVAL 2 MINUTE) < #{heartbeatTime}


    and t.machine_id= #{machineId}


    and t.machine_code like concat('%', #{machineCode}, '%')


    and t.location_name like concat('%', #{locationName}, '%')


    and t.factory_id= #{factoryId}


    and t.status_cd= #{statusCd}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.machine_name like concat('%', #{machineName}, '%')
